20: function parseIsoDate(value: string): Date | null {
21:   const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value.trim());
22:   if (!match) {
23:     return null;
24:   }
25: 
26:   const year = Number(match[1]);
27:   const month = Number(match[2]);
28:   const day = Number(match[3]);
29:   if (year < 1900 || month < 1 || month > 12 || day < 1) {
30:     return null;
31:   }
32: 
33:   const parsed = new Date(year, month - 1, day);
34:   if (
35:     parsed.getFullYear() !== year ||
36:     parsed.getMonth() !== month - 1 ||
37:     parsed.getDate() !== day
38:   ) {
39:     return null;
40:   }
