44: /** 18th birthday must have occurred on or before today's local calendar date. */
45: export function isLegalAge(birthDateIso: string, today: Date = new Date()): boolean {
46:   const birthDate = parseIsoDate(birthDateIso);
47:   if (!birthDate) {
