59:   if (anniversaryMonth === 1 && anniversaryDay === 29 && !isLeapYear(turning18Year)) {
60:     anniversaryDay = 28;
61:   }
62: 
63:   const turns18 = new Date(turning18Year, anniversaryMonth, anniversaryDay);
64:   return turns18 <= localToday;
65: }
