import { DOCUMENT } from '@angular/common';
import { provideHttpClient } from '@angular/common/http';
import { provideHttpClientTesting } from '@angular/common/http/testing';
import { provideLocationMocks } from '@angular/common/testing';
import { TestBed } from '@angular/core/testing';
import { provideRouter, RouterOutlet } from '@angular/router';

import { App } from './app';
import { API_BASE_URL } from './core/tokens/api-base-url.token';
import { UI_COPY } from './core/i18n/ui-copy';

describe('App shell', () => {
  beforeEach(async () => {
    await TestBed.configureTestingModule({
      imports: [App],
      providers: [
        provideRouter([]),
        provideHttpClient(),
        provideHttpClientTesting(),
        provideLocationMocks(),
        { provide: API_BASE_URL, useValue: 'http://strapi.test' },
      ],
    }).compileComponents();
  });

  it('creates the standalone App shell', () => {
    const fixture = TestBed.createComponent(App);

    expect(fixture.componentInstance).toBeTruthy();
  });

  it('renders the header, country switcher and router outlet (no hard-coded page title)', async () => {
    const fixture = TestBed.createComponent(App);
    await fixture.whenStable();
    const host = fixture.nativeElement as HTMLElement;

    expect(host.querySelector('header.app-header')).not.toBeNull();
    expect(host.querySelector('main.app-main')).not.toBeNull();
    expect(host.querySelector('router-outlet')).not.toBeNull();
    expect(TestBed.createComponent(App).debugElement.queryAll((node) => node.name === 'router-outlet').length).toBe(1);

    const brand = host.querySelector('.app-header__brand');
    expect(brand?.textContent).toContain(UI_COPY.brand);

    const switcher = host.querySelector<HTMLSelectElement>('#country-switcher');
    expect(switcher).not.toBeNull();
    expect(switcher?.tagName).toBe('SELECT');
    expect(Array.from(switcher?.options ?? []).map((option) => option.value)).toEqual(['co', 'cl']);

    const switcherLabel = host.querySelector('label[for="country-switcher"]');
    expect(switcherLabel?.textContent).toContain(UI_COPY.countryLabel);

    // US-01 chrome copy is shared/neutral; the page heading belongs to the routed page.
    expect(host.querySelector('h1')).toBeNull();
  });

  it('sets the document language from the route country context', async () => {
    const fixture = TestBed.createComponent(App);
    await fixture.whenStable();
    const document = TestBed.inject(DOCUMENT);

    expect(document.documentElement.lang).toBe('es-CO');
  });

  it('provides a RouterOutlet so lazy wizard routes can render', () => {
    const fixture = TestBed.createComponent(App);
    fixture.detectChanges();

    expect(fixture.debugElement.query((node) => node.injector.get(RouterOutlet, null) !== null)).toBeTruthy();
    expect(TestBed.inject(API_BASE_URL)).toBe('http://strapi.test');
  });
});

import { FormControl } from '@angular/forms';
import { describe, expect, it } from 'vitest';

import { vehicleYearValidator } from '../../features/quote/dynamic-form.factory';
import {
  isLegalAge,
  isValidClRut,
  isValidCoDocument,
  normalizeClRut,
  normalizePlate,
  vehicleYearBounds,
} from './domain-validators';

const TODAY_2026_11_23 = new Date(2026, 10, 23);

describe('isLegalAge (US01-U03, US01-U04, G1/G2/G3)', () => {
  it('accepts a birth date that turns 18 exactly today (local calendar date)', () => {
    expect(isLegalAge('2008-11-23', TODAY_2026_11_23)).toBe(true);
    // Time of day must not change the calendar-date comparison.
    expect(isLegalAge('2008-11-23', new Date(2026, 10, 23, 23, 59, 59))).toBe(true);
  });

  it('rejects a birth date one day younger than 18 (17 years 364 days)', () => {
    expect(isLegalAge('2008-11-24', TODAY_2026_11_23)).toBe(false);
  });

  it('applies the 28-Feb rule for 29-Feb birthdays in non-leap years', () => {
    expect(isLegalAge('2008-02-29', new Date(2026, 1, 27))).toBe(false);
    expect(isLegalAge('2008-02-29', new Date(2026, 1, 28))).toBe(true);
    expect(isLegalAge('2008-02-29', new Date(2026, 2, 1))).toBe(true);
  });

  it('rejects future birth dates and dates before the 1900-01-01 sanity floor', () => {
    expect(isLegalAge('2026-11-24', TODAY_2026_11_23)).toBe(false);
    expect(isLegalAge('1899-12-31', TODAY_2026_11_23)).toBe(false);
    // The floor itself is a parseable date and is accepted once adulthood is reached.
    expect(isLegalAge('1900-01-01', new Date(2018, 0, 1))).toBe(true);
  });

  it('rejects impossible, malformed and empty calendar dates', () => {
    expect(isLegalAge('2026-02-30', TODAY_2026_11_23)).toBe(false);
    expect(isLegalAge('23/11/2008', TODAY_2026_11_23)).toBe(false);
    expect(isLegalAge('', TODAY_2026_11_23)).toBe(false);
  });
});

describe('vehicleYearBounds / vehicleYearValidator (US01-U05, G4)', () => {
  it('computes currentYear - 20 .. currentYear + 1', () => {
    expect(vehicleYearBounds(new Date(2026, 10, 23))).toEqual({ min: 2006, max: 2027 });
    expect(vehicleYearBounds(new Date(2027, 0, 1))).toEqual({ min: 2007, max: 2028 });
  });

  it('accepts 2006 and 2027 in 2026 but rejects 2005, 2028 and fractional years', () => {
    const validator = vehicleYearValidator(TODAY_2026_11_23);

    expect(validator(new FormControl(2006))).toBeNull();
    expect(validator(new FormControl(2027))).toBeNull();
    expect(validator(new FormControl(2005))).toEqual({ vehicleYear: true });
    expect(validator(new FormControl(2028))).toEqual({ vehicleYear: true });
    expect(validator(new FormControl(2026.5))).toEqual({ vehicleYear: true });
  });
});

describe('isValidClRut / normalizeClRut (US01-U06, G8)', () => {
  it('accepts dotted, dashed, bare and lowercase-k forms with a valid módulo-11 digit', () => {
    expect(isValidClRut('12.345.678-5')).toBe(true);
    expect(isValidClRut('12345678-5')).toBe(true);
    expect(isValidClRut('123456785')).toBe(true);
    expect(isValidClRut('12.345.6789')).toBe(true);
    expect(isValidClRut('10.000.019-k')).toBe(true);
    expect(isValidClRut('10000019-K')).toBe(true);
  });

  it('rejects an invalid check digit and malformed bodies', () => {
    expect(isValidClRut('12.345.678-9')).toBe(false);
    expect(isValidClRut('10.000.019-9')).toBe(false);
    expect(isValidClRut('123-4')).toBe(false);
    expect(isValidClRut('12.345.678-A')).toBe(false);
    expect(isValidClRut('')).toBe(false);
  });

  it('normalises to canonical body-dash-checkdigit form with an uppercase K', () => {
    expect(normalizeClRut('12.345.678-5')).toBe('12345678-5');
    expect(normalizeClRut('123456785')).toBe('12345678-5');
    expect(normalizeClRut('10.000.019-k')).toBe('10000019-K');
    expect(normalizeClRut(' 12.345.678 5 ')).toBe('12345678-5');
    expect(normalizeClRut('not-a-rut')).toBe('NOTARUT');
  });
});

describe('isValidCoDocument (US01-U07, G6)', () => {
  it('enforces 6-10 digits for CC', () => {
    expect(isValidCoDocument('CC', '123456')).toBe(true);
    expect(isValidCoDocument('CC', '1023456789')).toBe(true);
    expect(isValidCoDocument('CC', '12345')).toBe(false);
    expect(isValidCoDocument('CC', '12345678901')).toBe(false);
  });

  it('enforces 6-12 digits for CE', () => {
    expect(isValidCoDocument('CE', '123456')).toBe(true);
    expect(isValidCoDocument('CE', '123456789012')).toBe(true);
    expect(isValidCoDocument('CE', '1234567890123')).toBe(false);
  });

  it('rejects non-digits, missing/unknown document types and trims input', () => {
    expect(isValidCoDocument('CC', '102345678A')).toBe(false);
    expect(isValidCoDocument('CC', '10 234 567')).toBe(false);
    expect(isValidCoDocument('', '1023456789')).toBe(false);
    expect(isValidCoDocument('TI', '1023456789')).toBe(false);
    expect(isValidCoDocument('cc', ' 1023456789 ')).toBe(true);
  });
});

describe('normalizePlate and seeded plate patterns (US01-U08, G7/G9)', () => {
  const coPattern = /^[A-Z]{3}[0-9]{3}$/;
  const clPattern = /^(?:[A-Z]{4}[0-9]{2}|[A-Z]{2}[0-9]{4})$/;

  it('trims and upper-cases plate input', () => {
    expect(normalizePlate(' abc123 ')).toBe('ABC123');
    expect(normalizePlate('abcd12')).toBe('ABCD12');
    expect(normalizePlate('aa1234')).toBe('AA1234');
  });

  it('matches the CO format ABC123 only after normalisation', () => {
    expect(coPattern.test(normalizePlate('xyz987'))).toBe(true);
    expect(coPattern.test('XYZ987')).toBe(true);
    expect(coPattern.test('AB1234')).toBe(false);
    expect(coPattern.test('ABC-123')).toBe(false);
    expect(coPattern.test('ABC 123')).toBe(false);
  });

  it('matches exactly the two CL formats ABCD12 and AA1234', () => {
    expect(clPattern.test('ABCD12')).toBe(true);
    expect(clPattern.test('AA1234')).toBe(true);
    expect(clPattern.test('ABC123')).toBe(false);
    expect(clPattern.test('ABC-12')).toBe(false);
  });
});

import { FormControl, Validators } from '@angular/forms';
import { TestBed } from '@angular/core/testing';
import { describe, expect, it } from 'vitest';

import type { FormFieldConfig, FormValue } from '../../core/models';
import { UI_COPY } from '../../core/i18n/ui-copy';
import { DynamicFieldComponent } from './dynamic-field';
import {
  DynamicFormFactory,
  clRutValidator,
  coerceDraftValue,
  coDocumentNumberValidator,
  dateBoundsValidator,
  legalAgeValidator,
  normalizeFieldValue,
  plateValidator,
  vehicleYearValidator,
} from './dynamic-form.factory';

function makeField(
  overrides: Partial<FormFieldConfig> & Pick<FormFieldConfig, 'key' | 'type'>,
): FormFieldConfig {
  return {
    id: 1,
    documentId: 'doc-1',
    key: overrides.key,
    label: overrides.key,
    type: overrides.type,
    required: false,
    validations: {},
    options: [],
    helpText: null,
    errorMessage: null,
    order: 1,
    country: 'CO',
    section: 'policyholder',
    ...overrides,
  };
}

describe('DynamicFormFactory', () => {
  let factory: DynamicFormFactory;

  beforeEach(() => {
    TestBed.configureTestingModule({});
    factory = TestBed.inject(DynamicFormFactory);
  });

  it('maps required to Validators.required for non-checkbox fields (US01-U02)', () => {
    const field = makeField({ key: 'fullName', type: 'text', required: true });
    const form = factory.createForm([field], {});
    const control = form.controls['fullName'];

    expect(control.hasError('required')).toBe(true);
    control.setValue('Camila Rodríguez');
    expect(control.valid).toBe(true);
    expect(form.valid).toBe(true);
  });

  it('maps required checkbox to Validators.requiredTrue and persists only booleans (US01-U21)', () => {
    const field = makeField({ key: 'acceptMarketing', type: 'checkbox', required: true });
    const form = factory.createForm([field], {});
    const control = form.controls['acceptMarketing'];

    expect(control.value).toBe(false);
    expect(control.hasError('required')).toBe(true);
    expect(form.invalid).toBe(true);

    control.setValue(true);
    expect(control.valid).toBe(true);
    expect(form.valid).toBe(true);
    expect(typeof control.value).toBe('boolean');
  });

  it('maps minLength and maxLength from Strapi validations (US01-U02)', () => {
    const field = makeField({
      key: 'fullName',
      type: 'text',
      validations: { minLength: 3, maxLength: 5 },
    });
    const control = factory.createForm([field], {}).controls['fullName'];

    control.setValue('ab');
    expect(control.hasError('minlength')).toBe(true);
    control.setValue('abc');
    expect(control.valid).toBe(true);
    control.setValue('abcdef');
    expect(control.hasError('maxlength')).toBe(true);
  });

  it('maps numeric min/max but ignores them for vehicleYear (US01-U02, US01-U05)', () => {
    const numeric = makeField({
      key: 'someNumber',
      type: 'number',
      validations: { min: 1900, max: 2027 },
    });
    const numericControl = factory.createForm([numeric], {}).controls['someNumber'];

    numericControl.setValue(1899);
    expect(numericControl.hasError('min')).toBe(true);
    numericControl.setValue(2028);
    expect(numericControl.hasError('max')).toBe(true);
    numericControl.setValue(2019);
    expect(numericControl.valid).toBe(true);

    const vehicleYear = makeField({
      key: 'vehicleYear',
      type: 'number',
      validations: { rule: 'vehicleYear', min: 1900, max: 1901 },
    });
    const yearControl = factory.createForm([vehicleYear], { vehicleYear: 2026 }).controls['vehicleYear'];
    expect(yearControl.hasError('min')).toBe(false);
    expect(yearControl.hasError('max')).toBe(false);
    expect(yearControl.valid).toBe(true);
  });

  it('maps pattern and domain plate validators (US01-U02, US01-U08)', () => {
    const text = makeField({
      key: 'documentNumber',
      type: 'text',
      validations: { pattern: '^[0-9]+$' },
    });
    const textControl = factory.createForm([text], {}).controls['documentNumber'];
    textControl.setValue('12345');
    expect(textControl.valid).toBe(true);
    textControl.setValue('12-345');
    expect(textControl.hasError('pattern')).toBe(true);

    const coPlate = makeField({
      key: 'licensePlate',
      type: 'text',
      validations: { rule: 'coPlate', pattern: '^[A-Z]{3}[0-9]{3}$' },
    });
    const plateControl = factory.createForm([coPlate], { licensePlate: 'ABC123' }).controls['licensePlate'];
    expect(plateControl.valid).toBe(true);
    plateControl.setValue('AB1234');
    expect(plateControl.hasError('plate')).toBe(true);
  });

  it('reacts to sibling documentType for coDocumentNumber (US01-U07)', () => {
    const fields: readonly FormFieldConfig[] = [
      makeField({ key: 'documentType', type: 'select' }),
      makeField({
        key: 'documentNumber',
        type: 'text',
        validations: { rule: 'coDocumentNumber', pattern: '^[0-9]+$' },
      }),
    ];

    const form = factory.createForm(fields, {
      documentType: '',
      documentNumber: '1023456789',
    });
    const typeControl = form.controls['documentType'];
    const numberControl = form.controls['documentNumber'];

    expect(numberControl.hasError('coDocumentNumber')).toBe(true);
    expect(form.hasError('coDocumentNumber')).toBe(true);
    expect(form.invalid).toBe(true);

    typeControl.setValue('CC');
    expect(numberControl.valid).toBe(true);
    expect(form.valid).toBe(true);

    // CE accepts 12 digits, CC does not.
    numberControl.setValue('123456789012');
    expect(numberControl.hasError('coDocumentNumber')).toBe(true);
    typeControl.setValue('CE');
    expect(numberControl.valid).toBe(true);

    numberControl.setValue('102345678A');
    expect(numberControl.hasError('pattern')).toBe(true);
    expect(numberControl.hasError('coDocumentNumber')).toBe(true);
  });

  it('standalone coDocumentNumberValidator passes only with a valid sibling type', () => {
    const control = new FormControl<FormValue>('123456');
    const documentType = new FormControl<FormValue>('CC');
    const parent = new FormGroupLike(documentType, control);
    void parent;

    expect(coDocumentNumberValidator()(control)).toEqual({ coDocumentNumber: true });
    documentType.setValue('CC');
    expect(coDocumentNumberValidator()(control)).toBeNull();
  });

  it('coerces restored draft values to the target control type (US01-U17)', () => {
    expect(coerceDraftValue(makeField({ key: 'vehicleYear', type: 'number' }), '2019')).toBe(2019);
    expect(coerceDraftValue(makeField({ key: 'vehicleYear', type: 'number' }), 'abc')).toBeNull();
    expect(coerceDraftValue(makeField({ key: 'vehicleYear', type: 'number' }), null)).toBeNull();
    expect(coerceDraftValue(makeField({ key: 'acceptMarketing', type: 'checkbox' }), 'true')).toBe(
      false,
    );
    expect(coerceDraftValue(makeField({ key: 'acceptMarketing', type: 'checkbox' }), true)).toBe(
      true,
    );
    expect(coerceDraftValue(makeField({ key: 'fullName', type: 'text' }), 123)).toBe('123');
    expect(coerceDraftValue(makeField({ key: 'fullName', type: 'text' }), null)).toBe('');
  });

  it('provides safe type defaults for newly added fields (US01-U12)', () => {
    expect(factory.defaultValue(makeField({ key: 'a', type: 'text' }))).toBe('');
    expect(factory.defaultValue(makeField({ key: 'b', type: 'number' }))).toBeNull();
    expect(factory.defaultValue(makeField({ key: 'c', type: 'checkbox' }))).toBe(false);
  });

  it('re-applies validators when the catalogue changes (US01-U12)', () => {
    const field = makeField({ key: 'fullName', type: 'text', required: false });
    const form = factory.createForm([field], { fullName: 'Camila Rodríguez' });
    expect(form.valid).toBe(true);

    factory.revalidate(
      form,
      [makeField({ key: 'fullName', type: 'text', required: true, validations: { minLength: 20 } })],
    );

    expect(form.controls['fullName'].hasError('required')).toBe(false);
    expect(form.controls['fullName'].hasError('minlength')).toBe(true);
    expect(form.invalid).toBe(true);
  });

  it('applies configured transforms on blur (US01-U08)', () => {
    expect(
      normalizeFieldValue(
        makeField({ key: 'licensePlate', type: 'text', validations: { rule: 'coPlate' } }),
        ' abc123 ',
      ),
    ).toBe('ABC123');
    expect(
      normalizeFieldValue(
        makeField({ key: 'documentNumber', type: 'text', validations: { rule: 'clRut' } }),
        '12.345.678-5',
      ),
    ).toBe('12345678-5');
    expect(
      normalizeFieldValue(
        makeField({ key: 'fullName', type: 'text', validations: { transform: 'trim' } }),
        '  Camila  ',
      ),
    ).toBe('Camila');
    expect(
      normalizeFieldValue(makeField({ key: 'n', type: 'number' }), '2019'),
    ).toBe('2019');
  });

  it('exposes pure domain validators used by the factory', () => {
    const today = new Date(2026, 10, 23);

    expect(legalAgeValidator(today)(new FormControl('2008-11-23'))).toBeNull();
    expect(legalAgeValidator(today)(new FormControl('2008-11-24'))).toEqual({ legalAge: true });
    expect(vehicleYearValidator(today)(new FormControl(2026.5))).toEqual({ vehicleYear: true });
    expect(clRutValidator()(new FormControl('12.345.678-5'))).toBeNull();
    expect(clRutValidator()(new FormControl('12.345.678-9'))).toEqual({ clRut: true });
    expect(dateBoundsValidator('1900-01-01')(new FormControl('1899-12-31'))).toEqual({
      dateRange: true,
    });
    expect(dateBoundsValidator('1900-01-01')(new FormControl('1990-01-01'))).toBeNull();
  });

  it('never throws on an invalid configured regex', () => {
    const field = makeField({
      key: 'fullName',
      type: 'text',
      validations: { pattern: '[' },
    });
    const control = factory.createForm([field], {}).controls['fullName'];
    control.setValue('Camila');
    expect(control.valid).toBe(true);
  });
});

/** Minimal parent-like control used to exercise the standalone sibling validator. */
class FormGroupLike {
  constructor(
    readonly documentType: FormControl<FormValue>,
    readonly documentNumber: FormControl<FormValue>,
  ) {
    (this.documentNumber as unknown as { parent: unknown }).parent = {
      get: (name: string): FormControl<FormValue> | null =>
        name === 'documentType' ? this.documentType : null,
    };
  }
}

describe('DynamicFieldComponent error message resolution (US01-U19)', () => {
  function render(field: FormFieldConfig, control: FormControl<FormValue>): HTMLElement {
    TestBed.configureTestingModule({ imports: [DynamicFieldComponent] });
    const fixture = TestBed.createComponent(DynamicFieldComponent);
    fixture.componentRef.setInput('field', field);
    fixture.componentRef.setInput('control', control);
    fixture.detectChanges();
    return fixture.nativeElement as HTMLElement;
  }

  it('renders the Strapi errorMessage verbatim for an invalid touched field', () => {
    const field = makeField({
      key: 'documentNumber',
      type: 'text',
      helpText: 'Ingresa tu RUT con o sin puntos y guion.',
      errorMessage: 'El RUT ingresado no es válido.',
      validations: { rule: 'clRut' },
    });
    const control = new FormControl<FormValue>('12.345.678-9', clRutValidator());
    control.markAsTouched();

    const host = render(field, control);
    const error = host.querySelector<HTMLElement>('#err-documentNumber');

    expect(error?.getAttribute('role')).toBe('alert');
    expect(error?.textContent?.trim()).toBe('El RUT ingresado no es válido.');
    expect(control.getAttribute('aria-invalid')).toBeNull();
    expect(host.querySelector('#help-documentNumber')?.textContent).toContain('RUT');
    expect(host.querySelector('input')?.getAttribute('aria-describedby')).toBe(
      'help-documentNumber err-documentNumber',
    );
  });

  it('falls back to neutral Spanish copy when errorMessage is null or blank', () => {
    const control = new FormControl<FormValue>('', Validators.required);
    control.markAsTouched();

    const nullHost = render(
      makeField({ key: 'fullName', type: 'text', required: true, errorMessage: null }),
      control,
    );
    expect(nullHost.querySelector('#err-fullName')?.textContent?.trim()).toBe(
      UI_COPY.fallbackValidation,
    );

    const blankHost = render(
      makeField({ key: 'fullName', type: 'text', required: true, errorMessage: '   ' }),
      control,
    );
    expect(blankHost.querySelector('#err-fullName')?.textContent?.trim()).toBe(
      UI_COPY.fallbackValidation,
    );
  });

  it('does not render an error for a valid or untouched control', () => {
    const field = makeField({
      key: 'licensePlate',
      type: 'text',
      errorMessage: 'La placa debe tener el formato ABC123.',
      validations: { rule: 'coPlate', pattern: '^[A-Z]{3}[0-9]{3}$' },
    });

    const validHost = render(field, new FormControl<FormValue>('XYZ987', plateValidator('^[A-Z]{3}[0-9]{3}$')));
    expect(validHost.querySelector('[role="alert"]')).toBeNull();

    const untouched = new FormControl<FormValue>('AB1234', plateValidator('^[A-Z]{3}[0-9]{3}$'));
    const untouchedHost = render(field, untouched);
    expect(untouchedHost.querySelector('[role="alert"]')).toBeNull();
  });
});

