import { TestBed } from '@angular/core/testing';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';

import type { CountryCode, PersistedWizardStateV1 } from '../models';
import { STORAGE_PORT, type StoragePort } from './storage.port';
import {
  DRAFT_TTL_MS,
  WizardPersistenceService,
  wizardStorageKey,
} from './wizard-persistence.service';

class FakeStorage implements StoragePort {
  readonly values = new Map<string, string>();
  throwOnGet = false;
  throwOnSet = false;
  throwOnRemove = false;

  getItem(key: string): string | null {
    if (this.throwOnGet) {
      throw new Error('storage disabled');
    }
    return this.values.get(key) ?? null;
  }

  setItem(key: string, value: string): void {
    if (this.throwOnSet) {
      throw new Error('quota exceeded');
    }
    this.values.set(key, value);
  }

  removeItem(key: string): void {
    if (this.throwOnRemove) {
      throw new Error('storage disabled');
    }
    this.values.delete(key);
  }
}

function makeState(overrides: Partial<PersistedWizardStateV1> = {}): PersistedWizardStateV1 {
  return {
    schemaVersion: 1,
    country: overrides.country ?? 'CO',
    savedAt: overrides.savedAt ?? new Date().toISOString(),
    step: overrides.step ?? 'policyholder',
    step1: overrides.step1 ?? {
      documentType: 'CC',
      documentNumber: '1023456789',
      vehicleYear: 2019,
      acceptMarketing: false,
    },
    selectedPlanDocumentId: overrides.selectedPlanDocumentId ?? null,
  };
}

describe('WizardPersistenceService (US01-U11, US01-U13, US01-U20)', () => {
  let storage: FakeStorage;
  let service: WizardPersistenceService;

  beforeEach(async () => {
    vi.spyOn(console, 'warn').mockImplementation(() => undefined);
    storage = new FakeStorage();
    await TestBed.configureTestingModule({
      providers: [{ provide: STORAGE_PORT, useValue: storage }],
    }).compileComponents();
    service = TestBed.inject(WizardPersistenceService);
  });

  afterEach(() => {
    vi.restoreAllMocks();
  });

  it('round-trips a saved draft with identical step1 values', () => {
    const state = makeState();

    service.save(state);

    expect(storage.values.has('wizard:state:v1:CO')).toBe(true);
    expect(service.load('CO')).toEqual(state);
  });

  it('scopes drafts by country and never hydrates a sibling country', () => {
    const co = makeState({ country: 'CO', step1: { city: 'BOG' } });
    service.save(co);

    expect(service.load('CL')).toBeNull();
    expect(storage.values.has(wizardStorageKey('CL' as CountryCode))).toBe(false);
    expect(service.load('CO')).toEqual(co);

    service.save(makeState({ country: 'CL', step1: { city: 'SCL' } }));
    expect(service.load('CO')).toEqual(co);
    expect(service.load('CL')?.step1).toEqual({ city: 'SCL' });
  });

  it('discards drafts older than the 2-hour TTL', () => {
    const expired = makeState({
      savedAt: new Date(Date.now() - DRAFT_TTL_MS - 1_000).toISOString(),
    });
    service.save(expired);

    expect(service.load('CO')).toBeNull();
    expect(storage.values.has(wizardStorageKey('CO'))).toBe(false);

    const fresh = makeState({
      savedAt: new Date(Date.now() - DRAFT_TTL_MS + 5_000).toISOString(),
    });
    service.save(fresh);
    expect(service.load('CO')).toEqual(fresh);
  });

  it('discards future-dated drafts', () => {
    service.save(makeState({ savedAt: new Date(Date.now() + 60_000).toISOString() }));

    expect(service.load('CO')).toBeNull();
    expect(storage.values.has(wizardStorageKey('CO'))).toBe(false);
  });

  it('discards mismatched schemaVersion and mismatched country', () => {
    const wrongVersion = {
      ...makeState(),
      schemaVersion: 2,
    } as unknown as PersistedWizardStateV1;
    service.save(wrongVersion);
    expect(service.load('CO')).toBeNull();
    expect(storage.values.has(wizardStorageKey('CO'))).toBe(false);

    const wrongCountry = { ...makeState(), country: 'CL' } as PersistedWizardStateV1;
    storage.values.set(wizardStorageKey('CO'), JSON.stringify(wrongCountry));
    expect(service.load('CO')).toBeNull();
    expect(storage.values.has(wizardStorageKey('CO'))).toBe(false);
  });

  it('returns null without throwing for corrupt JSON', () => {
    storage.values.set(wizardStorageKey('CO'), '{not json');

    expect(() => service.load('CO')).not.toThrow();
    expect(service.load('CO')).toBeNull();
  });

  it('clears only the requested country key', () => {
    service.save(makeState({ country: 'CO' }));
    service.save(makeState({ country: 'CL' }));

    service.clear('CO');

    expect(service.load('CO')).toBeNull();
    expect(service.load('CL')?.country).toBe('CL');
  });

  it('degrades gracefully when the injected STORAGE_PORT throws (US01-U20)', () => {
    storage.throwOnGet = true;
    expect(() => service.load('CO')).not.toThrow();
    expect(service.load('CO')).toBeNull();

    storage.throwOnGet = false;
    storage.throwOnSet = true;
    expect(() => service.save(makeState())).not.toThrow();
    expect(storage.values.size).toBe(0);

    storage.throwOnSet = false;
    storage.values.set(wizardStorageKey('CO'), JSON.stringify(makeState()));
    storage.throwOnRemove = true;
    expect(() => service.clear('CO')).not.toThrow();
    expect(storage.values.has(wizardStorageKey('CO'))).toBe(true);
  });

  it('uses the documented storage key shape', () => {
    expect(wizardStorageKey('CO')).toBe('wizard:state:v1:CO');
    expect(wizardStorageKey('CL')).toBe('wizard:state:v1:CL');
  });
});

import { provideLocationMocks } from '@angular/common/testing';
import { Component } from '@angular/core';
import { TestBed } from '@angular/core/testing';
import { provideRouter, Router } from '@angular/router';
import { beforeEach, describe, expect, it } from 'vitest';

import { toCountryCode, toRouteSegment } from './country-catalog';
import { CountryContextService } from './country-context.service';

@Component({ template: '', standalone: true })
class RouteTargetComponent {}

describe('toCountryCode / toRouteSegment', () => {
  it('canonicalises co/CO/cl/CL and falls back to CO for unknown values', () => {
    expect(toCountryCode('co')).toBe('CO');
    expect(toCountryCode('CO')).toBe('CO');
    expect(toCountryCode('cl')).toBe('CL');
    expect(toCountryCode('CL')).toBe('CL');
    expect(toCountryCode('xx')).toBe('CO');
    expect(toCountryCode(null)).toBe('CO');
    expect(toCountryCode(undefined)).toBe('CO');
    expect(toRouteSegment('CL')).toBe('cl');
    expect(toRouteSegment('xx')).toBe('co');
  });
});

describe('CountryContextService (US01-U14)', () => {
  let router: Router;

  beforeEach(async () => {
    await TestBed.configureTestingModule({
      providers: [
        provideLocationMocks(),
        provideRouter([
          { path: ':country/quote/plans', component: RouteTargetComponent },
          { path: ':country/quote', component: RouteTargetComponent },
          { path: '**', component: RouteTargetComponent },
        ]),
      ],
    }).compileComponents();
    router = TestBed.inject(Router);
    await router.navigateByUrl('/');
  });

  it('derives Colombia context from the canonical lowercase route param', async () => {
    await router.navigateByUrl('/co/quote');
    const context = TestBed.inject(CountryContextService);

    expect(context.country()).toBe('CO');
    expect(context.locale()).toBe('es-CO');
    expect(context.currency()).toBe('COP');
    expect(context.entry().displayName).toBe('Colombia');
    expect(context.currentStep()).toBe('policyholder');
    expect(context.quotePath()).toBe('/co/quote');
    expect(context.quotePath('plans')).toBe('/co/quote/plans');
    expect(context.pathFor('CL')).toBe('/cl/quote');
  });

  it('derives Chile context from /cl/quote', async () => {
    await router.navigateByUrl('/cl/quote');
    const context = TestBed.inject(CountryContextService);

    expect(context.country()).toBe('CL');
    expect(context.locale()).toBe('es-CL');
    expect(context.currency()).toBe('CLP');
    expect(context.entry().displayName).toBe('Chile');
    expect(context.quotePath('plans')).toBe('/cl/quote/plans');
  });

  it('normalises uppercase CO and CL route params', async () => {
    await router.navigateByUrl('/CO/quote');
    const context = TestBed.inject(CountryContextService);
    expect(context.country()).toBe('CO');

    await router.navigateByUrl('/CL/quote');
    expect(context.country()).toBe('CL');
  });

  it('recognises the plans step from the router URL', async () => {
    await router.navigateByUrl('/cl/quote/plans');
    const context = TestBed.inject(CountryContextService);

    expect(context.currentStep()).toBe('plans');
    expect(context.country()).toBe('CL');
  });

  it('falls back to Colombia for an unknown country param', async () => {
    await router.navigateByUrl('/xx/quote');
    const context = TestBed.inject(CountryContextService);

    expect(context.country()).toBe('CO');
    expect(context.locale()).toBe('es-CO');
  });

  it('reacts to NavigationEnd when switching country at runtime', async () => {
    const context = TestBed.inject(CountryContextService);
    expect(context.country()).toBe('CO');

    await router.navigateByUrl('/cl/quote');
    expect(context.country()).toBe('CL');

    await router.navigateByUrl('/co/quote');
    expect(context.country()).toBe('CO');
  });
});

import { provideLocationMocks } from '@angular/common/testing';
import { TestBed } from '@angular/core/testing';
import {
  ActivatedRouteSnapshot,
  Router,
  RouterStateSnapshot,
  UrlTree,
  convertToParamMap,
  provideRouter,
} from '@angular/router';
import { beforeEach, describe, expect, it } from 'vitest';

import { countryRouteGuard } from './country-route.guard';

function routeWithCountry(country: string | null): ActivatedRouteSnapshot {
  return {
    paramMap: convertToParamMap(country === null ? {} : { country }),
  } as ActivatedRouteSnapshot;
}

describe('countryRouteGuard (US01-U14, AC1/E03)', () => {
  let router: Router;
  const state = {} as RouterStateSnapshot;

  beforeEach(async () => {
    await TestBed.configureTestingModule({
      providers: [provideLocationMocks(), provideRouter([])],
    }).compileComponents();
    router = TestBed.inject(Router);
  });

  function activate(country: string | null): true | UrlTree {
    return TestBed.runInInjectionContext(() => countryRouteGuard(routeWithCountry(country), state));
  }

  it('allows canonical lowercase co and cl segments', () => {
    expect(activate('co')).toBe(true);
    expect(activate('cl')).toBe(true);
  });

  it('redirects uppercase CO to /co/quote', () => {
    const result = activate('CO');

    expect(result).toBeInstanceOf(UrlTree);
    expect(router.serializeUrl(result as UrlTree)).toBe('/co/quote');
  });

  it('redirects uppercase CL to /cl/quote', () => {
    const result = activate('CL');

    expect(result).toBeInstanceOf(UrlTree);
    expect(router.serializeUrl(result as UrlTree)).toBe('/cl/quote');
  });

  it('redirects an unknown country to /co/quote (never an empty catalogue)', () => {
    for (const raw of ['xx', 'MX', 'colombia', '']) {
      const result = activate(raw);
      expect(result).toBeInstanceOf(UrlTree);
      expect(router.serializeUrl(result as UrlTree)).toBe('/co/quote');
    }
  });

  it('redirects a missing param to /co/quote', () => {
    const result = activate(null);

    expect(result).toBeInstanceOf(UrlTree);
    expect(router.serializeUrl(result as UrlTree)).toBe('/co/quote');
  });
});

